import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using Quickselect algorithm.
    Average time complexity is O(n), worst case O(n^2) depending on the pivot choice.
    """

    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # We want the k-th largest, so use '>'
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left: int, right: int, k: int) -> int:
        if left == right:
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    return quickselect(0, len(nums) - 1, k - 1)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using the Median of Medians algorithm.
    The time complexity is O(n) for average case and O(n) for the worst case.
    """

    def median_of_medians(left: int, right: int) -> int:
        sublists = [nums[i:i + 5] for i in range(left, right + 1, 5)]
        medians = []

        for sublist in sublists:
            medians.append(sorted(sublist)[len(sublist) // 2])

        if len(medians) <= 5:
            return sorted(medians)[len(medians) // 2]
        else:
            return median_of_medians(0, len(medians) - 1)

    def partition(left: int, right: int, pivot: int) -> int:
        pivot_value = nums[pivot]
        nums[pivot], nums[right] = nums[right], nums[pivot]
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left: int, right: int, k: int) -> int:
        if left == right:
            return nums[left]

        pivot_index = median_of_medians(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    return quickselect(0, len(nums) - 1, k - 1)

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using a modified counting sort approach.
    Time complexity is O(n + m), where n is the number of elements and m is the range of the input numbers.
    """

    if not nums or k <= 0 or k > len(nums):
        raise ValueError("Invalid input: check your list and k value.")

    max_num = max(nums)
    min_num = min(nums)
    range_of_elements = max_num - min_num + 1

    count = [0] * range_of_elements

    for num in nums:
        count[num - min_num] += 1

    # Traverse the count array in reverse to find the k-th largest element
    for i in range(range_of_elements - 1, -1, -1):
        if count[i] > 0:
            k -= count[i]
            if k <= 0:
                return i + min_num

    return -1  # just in case; should never hit this line

def kth_largest(nums: list[int], k: int) -> int:
    """
    Returns the k-th largest element in an unsorted list using a modified binary search approach.
    Time complexity is O(n) on average, and O(n^2) in the worst case.
    """

    def count_greater(x: int) -> int:
        return sum(1 for num in nums if num > x)

    left, right = min(nums), max(nums)

    while left <= right:
        mid = (left + right) // 2
        count = count_greater(mid)

        if count == k:
            return mid
        elif count < k:
            right = mid - 1
        else:
            left = mid + 1

    return -1  # Should never reach here if input is valid
